  const [updated] = await db.update(adminUsers).set({ passwordHash: await bcrypt.hash(password, PASSWORD_ROUNDS), passwordChangedAt: now, sessionVersion: sql`${adminUsers.sessionVersion} + 1`, updatedAt: now }).where(eq(adminUsers.id, targe
